"use strict";
const NOURBEST_VERSION="3.0.0";

const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const store = {
  get(key, fallback) { try { return JSON.parse(localStorage.getItem(`nourbest:${key}`)) ?? fallback; } catch { return fallback; } },
  set(key, value) { try{localStorage.setItem(`nourbest:${key}`, JSON.stringify(value));}catch{} window.NourDB?.set(key,value).catch(error=>console.warn("IndexedDB write failed",error)); }
};
const makeId = () => globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(16).slice(2)}`;

const APPS = [
  {id:"files",name:"الملفات",icon:"▰",color:"#2c8cff",dock:true,desktop:true},
  {id:"notes",name:"الملاحظات",icon:"✎",color:"#ffb82e",dock:true,desktop:true},
  {id:"terminal",name:"الطرفية",icon:">_",color:"#1d3d38",dock:true,desktop:true},
  {id:"calculator",name:"الحاسبة",icon:"±",color:"#ff7338",dock:true},
  {id:"gallery",name:"المعرض",icon:"◇",color:"#e450a4",dock:true},
  {id:"tasks",name:"المهام",icon:"✓",color:"#38c98f",desktop:true},
  {id:"clocktools",name:"الوقت والتركيز",icon:"◷",color:"#27b8c5",desktop:true},
  {id:"converter",name:"محوّل الوحدات",icon:"⇄",color:"#4f8cff"},
  {id:"media",name:"مشغل الصوت",icon:"♪",color:"#d85bb5"},
  {id:"recorder",name:"مسجل الصوت",icon:"●",color:"#ef5d67"},
  {id:"qrtools",name:"QR",icon:"▦",color:"#111827"},
  {id:"diagnostics",name:"تشخيص النظام",icon:"◉",color:"#4bb98c"},
  {id:"systemcenter",name:"مركز النظام",icon:"⚡",color:"#5269d8",desktop:true},
  {id:"browser",name:"Nour Web",icon:"◎",color:"#687cff",desktop:true},
  {id:"settings",name:"الإعدادات",icon:"⚙",color:"#69788e",dock:true},
  {id:"about",name:"حول النظام",icon:"ن",color:"#7a63ff"}
];
if(window.NourPlugins)APPS.push(...NourPlugins.apps.map(({id,name,icon,color,dock,desktop})=>({id,name,icon,color,dock,desktop})));

const state = {
  windows:new Map(), z:50, active:null,
  notes:store.get("notes",[{id:makeId(),title:"مرحبًا بك",body:"هذه مساحتك الخاصة في NourBest OS.\n\nتُحفظ الملاحظات محليًا على جهازك.",updated:Date.now()}]),
  tasks:store.get("tasks",[]),
  files:store.get("files",[{id:makeId(),type:"folder",name:"المستندات",updated:Date.now()},{id:makeId(),type:"text",name:"مرحبًا.txt",content:"مرحبًا بك في NourBest OS",updated:Date.now()}]),
  profile:store.get("profile",{name:""}), preferences:store.get("preferences",{}), backups:store.get("backups",[]), logs:store.get("logs",[]), noteFolders:store.get("noteFolders",[]), currentNoteFolder:"all", taskFilter:"all", taskPriority:"all", currentDesktop:store.get("currentDesktop",0), contextWindow:null, currentFolder:null, fileView:"active", fileSort:"name", fileQuery:"", selectedFiles:new Set()
};
const system = $("#system"), windowLayer = $("#window-layer"), toast = $("#toast");

function icon(app, className="app-icon") { return `<span class="${className}" style="--icon:${app.color}">${app.icon}</span>`; }
function escapeHTML(value="") { return String(value).replace(/[&<>'"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c])); }
function notify(message) { toast.textContent=message; toast.classList.add("show"); clearTimeout(notify.timer); notify.timer=setTimeout(()=>toast.classList.remove("show"),2200); }
function systemLog(level,message){state.logs.unshift({time:Date.now(),level,message:String(message)});state.logs=state.logs.slice(0,100);store.set("logs",state.logs);}
function appById(id){ return APPS.find(app=>app.id===id); }
function isEditable(target){ return target instanceof HTMLElement && (target.matches("input,textarea,select,[contenteditable=true]") || !!target.closest("input,textarea,select,[contenteditable=true]")); }

function renderShell(){
  const dockIds=state.preferences.dockApps||APPS.filter(a=>a.dock).map(a=>a.id);$("#dock").innerHTML=APPS.filter(a=>dockIds.includes(a.id)).map(a=>`<button data-open="${a.id}" aria-label="${a.name}" title="${a.name}">${icon(a)}</button>`).join("");
  $("#app-grid").innerHTML=APPS.map(a=>`<button class="app-card" data-open="${a.id}">${icon(a)}<span>${a.name}</span></button>`).join("");
  $("#desktop-icons").innerHTML=APPS.filter(a=>a.desktop).map(a=>`<button class="desktop-app" data-open="${a.id}">${icon(a)}<span>${a.name}</span></button>`).join("");
  updateSearch(""); detectDevice(); applyPreferences();
}

function detectDevice(){
  const ua=navigator.userAgent;
  const label=/iPhone|iPad/.test(ua)?"Apple / iOS":/Android/.test(ua)?"Android / Harmony":/Windows/.test(ua)?"Windows":/Linux/.test(ua)?"Linux":"منصة ويب حديثة";
  $("#device-label").textContent=label;
}

function tick(){
  const now=new Date(), time=now.toLocaleTimeString("ar-SA",{hour:"2-digit",minute:"2-digit",hour12:!!state.preferences.clock12}), date=now.toLocaleDateString("ar-SA",{weekday:"long",day:"numeric",month:"long"});
  $("#clock").textContent=time; $("#widget-time").textContent=time; $("#widget-date").textContent=date; $("#lock-time").textContent=time; $("#lock-date").textContent=date; $("#calendar-time").textContent=time; $("#calendar-full-date").textContent=date;
  const hour=now.getHours(),base=hour<12?"صباح النور":hour<18?"مساء الإبداع":"مساء النور"; $("#greeting").textContent=state.profile.name?`${base}، ${state.profile.name}`:base;
}

function renderCalendar(){
  const now=new Date(), year=now.getFullYear(), month=now.getMonth(), first=new Date(year,month,1).getDay(), count=new Date(year,month+1,0).getDate();
  const gregorian=now.toLocaleDateString("ar-SA",{month:"long",year:"numeric"}),hijri=now.toLocaleDateString("ar-SA-u-ca-islamic",{month:"long",year:"numeric"});$("#month-title").textContent=state.preferences.calendar==="hijri"?hijri:state.preferences.calendar==="gregorian"?gregorian:`${gregorian} · ${hijri}`;
  let cells=["أح","إث","ثل","أر","خم","جم","سب"].map(d=>`<span class="day-name">${d}</span>`).join("");for(let i=0;i<first;i++)cells+="<span></span>";for(let d=1;d<=count;d++){const iso=`${year}-${String(month+1).padStart(2,"0")}-${String(d).padStart(2,"0")}`,hasTask=state.tasks.some(t=>t.due?.startsWith(iso)&&!t.archived);cells+=`<span class="${d===now.getDate()?"today ":""}${hasTask?"task-day":""}" data-calendar-date="${iso}">${d.toLocaleString("ar-SA")}</span>`;}$("#month-days").innerHTML=cells;
}

function closePanels(except="") { ["launcher","quick","search-panel","calendar","task-switcher","desktop-switcher","window-context"].forEach(id=>{if(id!==except) $("#"+id).hidden=true;}); }
function togglePanel(id){ const panel=$("#"+id), opening=panel.hidden; closePanels(opening?id:""); panel.hidden=!opening; if(opening) $("input",panel)?.focus(); }

function focusWindow(win,id){ state.z++; win.style.zIndex=state.z; state.active=id; $("#active-app-label").textContent=appById(id)?.name||"سطح المكتب"; $$(".dock button").forEach(b=>b.classList.toggle("running",state.windows.has(b.dataset.open))); }
function openApp(id){
  const app=appById(id); if(!app) return;
  closePanels(); let win=state.windows.get(id);
  if(win){state.currentDesktop=Number(win.dataset.desktop);store.set("currentDesktop",state.currentDesktop);win.classList.remove("minimized");applyDesktopVisibility();focusWindow(win,id);return;}
  win=$("#window-template").content.firstElementChild.cloneNode(true);win.dataset.app=id;win.dataset.desktop=String(store.get(`windowDesktop:${id}`,state.currentDesktop));$(".window-title strong",win).textContent=app.name;$(".window-icon",win).textContent=app.icon;$(".window-body",win).innerHTML=renderApp(id);const layout=store.get(`window:${id}`,null);if(layout&&innerWidth>720)Object.assign(win.style,layout);windowLayer.append(win);state.windows.set(id,win);bindApp(id,win);bindWindow(win,id);focusWindow(win,id);saveOpenSession();applyDesktopVisibility();renderTaskSwitcher();
}
function closeApp(id){const win=state.windows.get(id);if(!win)return;win.remove();state.windows.delete(id);saveOpenSession();const remaining=[...state.windows.entries()].filter(([,w])=>!w.classList.contains("minimized")&&Number(w.dataset.desktop)===state.currentDesktop);if(remaining.length){const[nextId,nextWin]=remaining.at(-1);focusWindow(nextWin,nextId);}else{state.active=null;$("#active-app-label").textContent=`سطح المكتب ${state.currentDesktop+1}`;}renderTaskSwitcher();$$('.dock button').forEach(b=>b.classList.toggle("running",state.windows.has(b.dataset.open)));}
function saveOpenSession(){store.set("openApps",[...state.windows.keys()]);}
function applyDesktopVisibility(){state.windows.forEach(win=>{win.hidden=Number(win.dataset.desktop)!==state.currentDesktop;});$("#active-app-label").textContent=`سطح المكتب ${state.currentDesktop+1}`;renderDesktopSwitcher();}
function bindWindow(win,id){
  win.addEventListener("pointerdown",()=>focusWindow(win,id));
  win.addEventListener("contextmenu",e=>{e.preventDefault();openWindowContext(id,e.clientX,e.clientY);});
  $(".window-controls",win).addEventListener("click",e=>{ const action=e.target.closest("button")?.dataset.windowAction; if(action==="close")closeApp(id); if(action==="minimize")win.classList.add("minimized"); if(action==="maximize")win.classList.toggle("maximized"); });
  const bar=$(".window-bar",win); let drag=null;
  bar.addEventListener("pointerdown",e=>{if(innerWidth<721||e.target.closest("button")||win.classList.contains("maximized"))return; const r=win.getBoundingClientRect(); drag={x:e.clientX-r.left,y:e.clientY-r.top}; bar.setPointerCapture(e.pointerId);});
  bar.addEventListener("pointermove",e=>{if(!drag)return; win.style.left=Math.max(0,Math.min(innerWidth-win.offsetWidth,e.clientX-drag.x))+"px"; win.style.top=Math.max(0,Math.min(innerHeight-win.offsetHeight-48,e.clientY-drag.y-48))+"px"; win.style.transform="none";});
  bar.addEventListener("pointerup",e=>{if(drag&&innerWidth>720){if(e.clientX<28){win.style.cssText+=`;left:0;top:0;transform:none;width:50%;height:calc(100% - 82px)`;}else if(e.clientX>innerWidth-28){win.style.cssText+=`;left:50%;top:0;transform:none;width:50%;height:calc(100% - 82px)`;}else if(e.clientY<70)win.classList.add("maximized");}drag=null;storeWindowLayout(id,win);});
  const handle=$(".resize-handle",win);let resize=null;handle.addEventListener("pointerdown",e=>{const r=win.getBoundingClientRect();resize={x:e.clientX,y:e.clientY,w:r.width,h:r.height};handle.setPointerCapture(e.pointerId);});handle.addEventListener("pointermove",e=>{if(!resize)return;win.style.width=Math.max(360,resize.w+e.clientX-resize.x)+"px";win.style.height=Math.max(260,resize.h+e.clientY-resize.y)+"px";});handle.addEventListener("pointerup",()=>{resize=null;storeWindowLayout(id,win);});
}
function openWindowContext(id,x,y){state.contextWindow=id;const menu=$("#window-context");menu.style.left=`${Math.min(x,innerWidth-230)}px`;menu.style.top=`${Math.min(y,innerHeight-280)}px`;menu.style.right="auto";menu.hidden=false;}
function storeWindowLayout(id,win){store.set(`window:${id}`,{left:win.style.left,top:win.style.top,width:win.style.width,height:win.style.height});}
function renderTaskSwitcher(){const list=$("#task-switcher-list");if(!list)return;list.innerHTML=state.windows.size?[...state.windows].map(([id,win])=>{const app=appById(id),preview=escapeHTML($(".window-body",win).innerText.slice(0,90));return `<article class="task-preview"><button data-switch-window="${id}">${icon(app)}<strong>${app.name}</strong><span>${preview}</span><small>سطح ${Number(win.dataset.desktop)+1}</small></button><button data-move-window="${id}">نقل</button></article>`;}).join(""):"<p>لا توجد نوافذ مفتوحة</p>";}
function renderDesktopSwitcher(){const list=$("[data-desktop-list]");if(!list)return;list.innerHTML=[0,1,2].map(index=>`<button data-desktop="${index}" class="${index===state.currentDesktop?"active":""}"><strong>سطح ${index+1}</strong><small>${[...state.windows.values()].filter(w=>Number(w.dataset.desktop)===index).length} نوافذ</small></button>`).join("");}
function switchDesktop(index){state.currentDesktop=Math.max(0,Math.min(2,index));store.set("currentDesktop",state.currentDesktop);applyDesktopVisibility();const visible=[...state.windows.entries()].filter(([,w])=>!w.hidden&&!w.classList.contains("minimized"));if(visible.length){const[id,win]=visible.at(-1);focusWindow(win,id);}closePanels();}
function arrangeWindows(layout){const wins=[...state.windows.values()].filter(w=>Number(w.dataset.desktop)===state.currentDesktop&&!w.classList.contains("minimized"));if(!wins.length)return;wins.forEach(w=>w.classList.remove("maximized"));if(layout==="halves"){wins.slice(0,2).forEach((w,i)=>Object.assign(w.style,{left:`${i*50}%`,top:"0",width:"50%",height:"calc(100% - 82px)",transform:"none"}));}else if(layout==="cascade"){wins.forEach((w,i)=>Object.assign(w.style,{left:`${30+i*35}px`,top:`${25+i*30}px`,width:"70%",height:"70%",transform:"none"}));}else{const cols=Math.ceil(Math.sqrt(wins.length)),rows=Math.ceil(wins.length/cols);wins.forEach((w,i)=>Object.assign(w.style,{left:`${i%cols*100/cols}%`,top:`${Math.floor(i/cols)*100/rows}%`,width:`${100/cols}%`,height:`calc(${100/rows}% - 82px)`,transform:"none"}));}wins.forEach(w=>storeWindowLayout(w.dataset.app,w));}

function renderApp(id){
  if(id==="files")return filesHTML();if(id==="notes")return notesHTML();if(id==="terminal")return terminalHTML();if(id==="calculator")return calculatorHTML();if(id==="gallery")return galleryHTML();if(id==="tasks")return tasksHTML();if(id==="clocktools")return clockToolsHTML();if(id==="converter")return converterHTML();if(id==="media")return mediaHTML();if(id==="recorder")return recorderHTML();if(id==="qrtools")return qrToolsHTML();if(id==="diagnostics")return diagnosticsHTML();if(id==="systemcenter")return systemCenterHTML();if(id==="browser")return browserHTML();if(id==="settings")return settingsHTML();const plugin=NourPlugins?.apps.find(app=>app.id===id);if(plugin)return plugin.render();return aboutHTML();
}

function filesHTML(){return `<div class="app-shell"><aside class="app-sidebar"><h3>الملفات</h3><button class="side-button active" data-file-view="active">الرئيسية</button><button class="side-button" data-file-view="recent">الأخيرة</button><button class="side-button" data-file-view="favorites">المفضلة</button><button class="side-button" data-file-view="trash">المحذوفات</button><button class="side-button" data-file-import>استيراد</button><button class="side-button" data-file-export>نسخة احتياطية</button><button class="side-button" data-native-files hidden>ملفات Linux الحقيقية</button><small data-storage-usage></small></aside><main class="app-content file-manager"><div class="toolbar"><div><button data-folder-up aria-label="المجلد السابق">↑</button> <strong data-breadcrumb>ملفاتي</strong></div><div><button data-bulk-trash disabled>حذف المحدد</button> <button data-text-new>+ ملف نصي</button> <button data-file-new>+ مجلد</button></div></div><div class="file-filters"><input data-file-search type="search" placeholder="ابحث في الملفات…"><select data-file-sort><option value="name">الاسم</option><option value="updated">التاريخ</option><option value="type">النوع</option><option value="size">الحجم</option></select></div><input type="file" data-file-picker hidden multiple><div class="file-grid" data-file-grid></div><section class="file-editor" data-file-editor hidden><div class="toolbar"><input data-file-name aria-label="اسم الملف"><div><button data-file-save>حفظ</button> <button data-editor-close>إغلاق</button></div></div><textarea data-file-content aria-label="محتوى الملف"></textarea></section></main></div>`;}
function normalizeFiles(){state.files=state.files.map(f=>({...f,parentId:f.parentId??null,favorite:!!f.favorite,deleted:!!f.deleted,size:f.size??new Blob([f.content||""]).size}));}
function renderFiles(win){normalizeFiles();let files=state.files.filter(f=>state.fileView==="trash"?f.deleted:!f.deleted);if(state.fileView==="active")files=files.filter(f=>f.parentId===state.currentFolder);if(state.fileView==="favorites")files=files.filter(f=>f.favorite);if(state.fileView==="recent")files=files.sort((a,b)=>b.updated-a.updated).slice(0,20);const q=state.fileQuery.trim().toLowerCase();if(q)files=files.filter(f=>(f.name+" "+(f.content||"")).toLowerCase().includes(q));files.sort((a,b)=>state.fileSort==="updated"?b.updated-a.updated:state.fileSort==="type"?a.type.localeCompare(b.type):state.fileSort==="size"?(b.size||0)-(a.size||0):a.name.localeCompare(b.name,"ar"));const grid=$("[data-file-grid]",win);grid.innerHTML=files.map(f=>`<article class="file-card ${state.selectedFiles.has(f.id)?"selected":""}" data-file-id="${f.id}"><label><input type="checkbox" data-file-select="${f.id}" ${state.selectedFiles.has(f.id)?"checked":""}> تحديد</label><b>${f.type==="folder"?"▰":f.type==="image"?"▧":"◆"}</b><strong>${escapeHTML(f.name)}</strong><small>${formatBytes(f.size||0)} · ${new Date(f.updated).toLocaleDateString("ar-SA")}</small><div>${f.deleted?`<button data-file-restore="${f.id}">استعادة</button><button data-file-destroy="${f.id}">حذف نهائي</button>`:`<button data-file-open="${f.id}">فتح</button><button data-file-rename="${f.id}">تسمية</button><button data-file-favorite="${f.id}">${f.favorite?"★":"☆"}</button><button data-file-copy="${f.id}">نسخ</button><button data-file-move="${f.id}">نقل</button>${f.type!=="folder"?`<button data-file-download="${f.id}">تنزيل</button>`:""}<button data-file-delete="${f.id}">حذف</button>`}</div></article>`).join("")||"<p>لا توجد عناصر هنا</p>";const folder=state.files.find(f=>f.id===state.currentFolder);$("[data-breadcrumb]",win).textContent=folder?.name||({favorites:"المفضلة",recent:"الأخيرة",trash:"المحذوفات"}[state.fileView]||"ملفاتي");$("[data-folder-up]",win).disabled=!folder;$("[data-bulk-trash]",win).disabled=!state.selectedFiles.size;}
function formatBytes(bytes){if(bytes<1024)return`${bytes} B`;if(bytes<1048576)return`${(bytes/1024).toFixed(1)} KB`;return`${(bytes/1048576).toFixed(1)} MB`;}

function notesHTML(){return `<div class="notes-layout"><aside class="notes-list"><div class="toolbar"><strong>ملاحظاتي</strong><button data-note-new>+</button></div><input data-note-search type="search" placeholder="بحث…"><div class="note-folders" data-note-folders></div><button data-note-folder-new>+ مجلد</button><div data-note-list></div></aside><main class="note-editor"><div class="toolbar note-actions"><small data-note-status>محفوظ</small><div><button data-note-pin>☆ تثبيت</button><button data-note-template>قالب</button><button data-note-replace>بحث واستبدال</button><button data-note-preview>معاينة</button><button data-note-history>السجل</button><button data-note-export>تصدير</button><button data-note-delete>حذف</button></div></div><input data-note-title aria-label="عنوان الملاحظة"><div class="note-meta"><input data-note-tags placeholder="وسوم مفصولة بفاصلة"><select data-note-folder aria-label="مجلد الملاحظة"></select><small data-note-count></small></div><textarea data-note-body aria-label="نص الملاحظة" placeholder="ابدأ الكتابة…"></textarea><section class="note-preview" data-note-preview-pane hidden></section><section class="note-history" data-note-history-pane hidden></section></main></div>`;}
function normalizeNotes(){state.notes=state.notes.map(n=>({...n,tags:n.tags||[],folderId:n.folderId||null,pinned:!!n.pinned,versions:n.versions||[]}));}
function renderNoteList(win,selected){normalizeNotes();const query=$("[data-note-search]",win)?.value.trim().toLowerCase()||"";let notes=state.notes.filter(n=>state.currentNoteFolder==="all"||n.folderId===state.currentNoteFolder);if(query)notes=notes.filter(n=>(n.title+" "+n.body+" "+n.tags.join(" ")).toLowerCase().includes(query));notes.sort((a,b)=>Number(b.pinned)-Number(a.pinned)||b.updated-a.updated);$("[data-note-list]",win).innerHTML=notes.map(n=>`<button class="${n.id===selected?"active":""}" data-note-id="${n.id}"><strong>${n.pinned?"★ ":""}${escapeHTML(n.title||"بدون عنوان")}</strong><br><small>${escapeHTML(n.tags.join(" · "))||new Date(n.updated).toLocaleDateString("ar-SA")}</small></button>`).join("")||"<p>لا توجد ملاحظات</p>";$("[data-note-folders]",win).innerHTML=`<button data-note-folder-filter="all" class="${state.currentNoteFolder==="all"?"active":""}">الكل</button>${state.noteFolders.map(f=>`<button data-note-folder-filter="${f.id}" class="${state.currentNoteFolder===f.id?"active":""}">${escapeHTML(f.name)}</button>`).join("")}`;const folderSelect=$("[data-note-folder]",win);folderSelect.innerHTML=`<option value="">بدون مجلد</option>${state.noteFolders.map(f=>`<option value="${f.id}">${escapeHTML(f.name)}</option>`).join("")}`;}
function selectNote(win,id){normalizeNotes();const note=state.notes.find(n=>n.id===id)||state.notes[0];if(!note)return;win.dataset.note=note.id;renderNoteList(win,note.id);$("[data-note-title]",win).value=note.title;$("[data-note-body]",win).value=note.body;$("[data-note-tags]",win).value=note.tags.join(", ");$("[data-note-folder]",win).value=note.folderId||"";$("[data-note-pin]",win).textContent=note.pinned?"★ مثبت":"☆ تثبيت";updateNoteCount(win);}
function updateNoteCount(win){const body=$("[data-note-body]",win).value,words=body.trim()?body.trim().split(/\s+/).length:0;$("[data-note-count]",win).textContent=`${words} كلمة · ${body.length} حرف · ${Math.max(1,Math.ceil(words/200))} د قراءة`;}

function terminalHTML(){ return `<div class="terminal"><div class="terminal-output">NourBest Shell 1.0\nاكتب help لعرض الأوامر.\n\n</div><form class="terminal-line"><span>user@nourbest:~$</span><input aria-label="أمر الطرفية" autocomplete="off" spellcheck="false"></form></div>`; }
function calculatorHTML(){const keys=["C","⌫","%","÷","sin(","cos(","tan(","√(","7","8","9","×","4","5","6","−","1","2","3","+","π","0",".","^","log(","(",")","="];return `<div class="calculator"><div class="calc-body scientific"><input class="calc-display" value="0" readonly aria-label="شاشة الحاسبة"><div class="calc-grid">${keys.map(k=>`<button class="${"÷×−+%^".includes(k)?"operator":k==="="?"equals":""}" data-calc="${k}">${k}</button>`).join("")}</div></div></div>`;}
