function tasksHTML(){return `<main class="app-content"><div class="toolbar"><h2>المهام</h2><strong data-task-stats></strong></div><form data-task-form class="task-form"><input name="text" placeholder="أضف مهمة جديدة…" required><input name="due" type="datetime-local" aria-label="الموعد"><select name="priority" aria-label="الأولوية"><option value="normal">عادية</option><option value="high">عالية</option><option value="low">منخفضة</option></select><select name="recurrence" aria-label="التكرار"><option value="none">بدون تكرار</option><option value="daily">يومي</option><option value="weekly">أسبوعي</option><option value="monthly">شهري</option></select><button class="primary">إضافة</button></form><div class="task-tabs">${[["all","الكل"],["today","اليوم"],["overdue","متأخرة"],["completed","مكتملة"],["archive","الأرشيف"]].map(([id,label])=>`<button data-task-filter="${id}">${label}</button>`).join("")}<select data-priority-filter><option value="all">كل الأولويات</option><option value="high">عالية</option><option value="normal">عادية</option><option value="low">منخفضة</option></select></div><div class="task-workspace"><div data-task-list></div><aside class="task-calendar" data-task-calendar><h3>اسحب المهمة إلى اليوم</h3><div data-task-calendar-grid></div></aside></div></main>`;}
function normalizeTasks(){state.tasks=state.tasks.map(t=>({...t,due:t.due||"",priority:t.priority||"normal",recurrence:t.recurrence||"none",subtasks:t.subtasks||[],archived:!!t.archived,created:t.created||Date.now()}));}
function renderTasks(win){
  normalizeTasks();const today=new Date().toISOString().slice(0,10),now=Date.now();
  let tasks=state.tasks.filter(t=>state.taskFilter==="archive"?t.archived:!t.archived);
  if(state.taskFilter==="today")tasks=tasks.filter(t=>t.due.startsWith(today));
  if(state.taskFilter==="overdue")tasks=tasks.filter(t=>t.due&&!t.done&&new Date(t.due).getTime()<now);
  if(state.taskFilter==="completed")tasks=tasks.filter(t=>t.done);
  if(state.taskPriority!=="all")tasks=tasks.filter(t=>t.priority===state.taskPriority);
  tasks.sort((a,b)=>({high:0,normal:1,low:2}[a.priority]-{high:0,normal:1,low:2}[b.priority])||(a.due||"9999").localeCompare(b.due||"9999"));
  $("[data-task-list]",win).innerHTML=tasks.length?tasks.map(t=>`<article class="task-card ${t.done?"done":""}" draggable="true" data-task-drag="${t.id}"><label><input type="checkbox" data-task-toggle="${t.id}" ${t.done?"checked":""}><strong>${t.priority==="high"?"🔴 ":t.priority==="low"?"🔵 ":""}${escapeHTML(t.text)}</strong></label><small>${t.due?new Date(t.due).toLocaleString("ar-SA"):"بدون موعد"}${t.recurrence!=="none"?` · ${t.recurrence}`:""}</small><div class="subtask-list">${t.subtasks.map(s=>`<label><input type="checkbox" data-subtask-toggle="${t.id}:${s.id}" ${s.done?"checked":""}>${escapeHTML(s.text)}</label>`).join("")}</div><div><button data-subtask-new="${t.id}">+ فرعية</button><button data-task-archive="${t.id}">${t.archived?"إلغاء الأرشفة":"أرشفة"}</button><button data-task-delete="${t.id}">حذف</button></div></article>`).join(""):"<p>لا توجد مهام في هذا القسم</p>";
  const completed=state.tasks.filter(t=>t.done).length,weekAgo=Date.now()-604800000,weekly=state.tasks.filter(t=>t.done&&(t.completedAt||0)>=weekAgo).length;$("[data-task-stats]",win).textContent=`${completed}/${state.tasks.length} مكتملة · ${weekly} هذا الأسبوع`;
  $$('[data-task-filter]',win).forEach(b=>b.classList.toggle("active",b.dataset.taskFilter===state.taskFilter));$("[data-priority-filter]",win).value=state.taskPriority;renderTaskCalendar(win);
}
function renderTaskCalendar(win){const grid=$("[data-task-calendar-grid]",win),now=new Date(),year=now.getFullYear(),month=now.getMonth(),first=new Date(year,month,1).getDay(),days=new Date(year,month+1,0).getDate();let html=["أح","إث","ثل","أر","خم","جم","سب"].map(d=>`<b>${d}</b>`).join("");for(let i=0;i<first;i++)html+="<span></span>";for(let day=1;day<=days;day++){const date=`${year}-${String(month+1).padStart(2,"0")}-${String(day).padStart(2,"0")}`,count=state.tasks.filter(t=>t.due.startsWith(date)&&!t.archived).length;html+=`<span data-task-drop="${date}">${day}${count?`<small>${count}</small>`:""}</span>`;}grid.innerHTML=html;}
