function bindSystemCenter(win){const refresh=async()=>{try{const release=await fetch(`./release.json?t=${Date.now()}`).then(r=>r.json());$("[data-release-status]",win).textContent=release.version===NOURBEST_VERSION?`أنت على أحدث إصدار ${release.version}`:`يتوفر ${release.version}`;$("[data-release-notes]",win).innerHTML=release.notes.map(n=>`<li>${escapeHTML(n)}</li>`).join("");}catch{$("[data-release-status]",win).textContent="تعذر الاتصال؛ النسخة الحالية تعمل دون إنترنت";}const keys=await caches.keys(),estimate=await navigator.storage?.estimate?.();$("[data-cache-status]",win).textContent=`${keys.length} حاويات كاش · ${navigator.serviceWorker?.controller?"Offline نشط":"Offline قيد التهيئة"}`;$("[data-system-storage]",win).textContent=estimate?`${formatBytes(estimate.usage||0)} مستخدم من ${formatBytes(estimate.quota||0)}`:"تقدير التخزين غير متاح";};$("[data-system-update]",win).onclick=async()=>{await navigator.serviceWorker?.getRegistration().then(r=>r?.update());await refresh();notify("اكتمل فحص التحديث");};$("[data-cache-refresh]",win).onclick=()=>{navigator.serviceWorker?.controller?.postMessage({type:"REFRESH_CACHE"});notify("جارٍ إعادة بناء الكاش");};$("[data-cache-clean]",win).onclick=async()=>{const keys=await caches.keys();await Promise.all(keys.filter(k=>k!=="nourbest-os-v3").map(k=>caches.delete(k)));await refresh();notify("تم تنظيف الكاش القديم");};$("[data-open-diagnostics]",win).onclick=()=>openApp("diagnostics");refresh();}
let installPrompt=null;
function bindSettings(win){$$('[data-theme]',win).forEach(b=>b.onclick=()=>{setTheme(b.dataset.theme);$("#appearance strong",win).textContent=b.dataset.theme;});$$('[data-settings-target]',win).forEach(b=>b.onclick=()=>{$$(".side-button",win).forEach(x=>x.classList.toggle("active",x===b));$("#"+b.dataset.settingsTarget,win)?.scrollIntoView({behavior:"smooth"});});$("[data-backup]",win).onclick=()=>downloadBlob("nourbest-backup.json",JSON.stringify({version:2,notes:state.notes,tasks:state.tasks,files:state.files,preferences:{theme:store.get("theme","default"),wallpaper:store.get("wallpaper","0")}},null,2),"application/json");$("[data-clear-local]",win).onclick=async()=>{if(confirm("مسح الملاحظات والمهام والتفضيلات المحلية؟")){Object.keys(localStorage).filter(k=>k.startsWith("nourbest:")).forEach(k=>localStorage.removeItem(k));await window.NourDB?.clear();location.reload();}};$("[data-install]",win).onclick=async()=>{if(installPrompt){installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;}else notify("في Safari: مشاركة ثم إضافة إلى الشاشة الرئيسية");};$("[data-check-update]",win).onclick=async()=>{const r=await navigator.serviceWorker?.getRegistration();await r?.update();notify(r?.waiting?"يوجد تحديث جاهز":"أنت تستخدم أحدث إصدار");};$("[data-large-text]",win).onchange=e=>{document.documentElement.style.fontSize=e.target.checked?"18px":"16px";store.set("largeText",e.target.checked);};$("[data-reduce-motion]",win).onchange=e=>document.body.classList.toggle("reduce-motion",e.target.checked);$("[data-capabilities]",win).textContent=[`المنصة: ${navigator.platform||"ويب"}`,`المعالج المنطقي: ${navigator.hardwareConcurrency||"غير معروف"}`,`الذاكرة: ${navigator.deviceMemory?`${navigator.deviceMemory} GB`:"غير متاحة"}`,`اللمس: ${navigator.maxTouchPoints||0}`].join(" · ");}
function enhanceSettings(win){const grid=$(".settings-grid",win),p=state.preferences;grid.insertAdjacentHTML("afterbegin",`<section class="setting-card"><h3>الملف الشخصي</h3><input data-profile-name value="${escapeHTML(state.profile.name)}" placeholder="الاسم"><input data-profile-avatar type="file" accept="image/*"><button data-profile-save>حفظ الملف</button></section><section class="setting-card"><h3>الخلفية والألوان</h3><input data-wallpaper-upload type="file" accept="image/*"><label>لون النظام <input data-accent type="color" value="${p.accent||"#58e6ff"}"></label><label>تمويه <input data-wallpaper-blur type="range" min="0" max="24" value="${p.blur||0}"></label><label>سطوع <input data-wallpaper-light type="range" min="40" max="120" value="${p.wallpaperBrightness||100}"></label></section><section class="setting-card"><h3>Dock</h3><label>الحجم <input data-dock-scale type="range" min="0.75" max="1.25" step="0.05" value="${p.dockScale||1}"></label><div data-dock-apps>${APPS.map(a=>`<label><input type="checkbox" value="${a.id}" ${(p.dockApps||APPS.filter(x=>x.dock).map(x=>x.id)).includes(a.id)?"checked":""}>${a.name}</label>`).join("")}</div></section><section class="setting-card"><h3>الوقت والتقويم</h3><label><input data-clock12 type="checkbox" ${p.clock12?"checked":""}> نظام 12 ساعة</label><select data-calendar-mode><option value="both">هجري وميلادي</option><option value="hijri">هجري</option><option value="gregorian">ميلادي</option></select><button data-notifications>تفعيل تذكيرات النظام</button></section>`);$("[data-calendar-mode]",win).value=p.calendar||"both";const savePrefs=()=>{store.set("preferences",state.preferences);applyPreferences();tick();renderCalendar();};$("[data-profile-save]",win).onclick=()=>{state.profile.name=$("[data-profile-name]",win).value.trim();store.set("profile",state.profile);applyPreferences();tick();notify("تم حفظ الملف الشخصي");};$("[data-profile-avatar]",win).onchange=e=>readImage(e.target.files[0],data=>{state.profile.avatar=data;store.set("profile",state.profile);applyPreferences();});$("[data-wallpaper-upload]",win).onchange=e=>readImage(e.target.files[0],data=>{state.preferences.wallpaperData=data;savePrefs();});$("[data-accent]",win).oninput=e=>{state.preferences.accent=e.target.value;savePrefs();};$("[data-wallpaper-blur]",win).oninput=e=>{state.preferences.blur=Number(e.target.value);savePrefs();};$("[data-wallpaper-light]",win).oninput=e=>{state.preferences.wallpaperBrightness=Number(e.target.value);savePrefs();};$("[data-dock-scale]",win).oninput=e=>{state.preferences.dockScale=Number(e.target.value);savePrefs();};$("[data-dock-apps]",win).onchange=()=>{state.preferences.dockApps=$$("input:checked",$("[data-dock-apps]",win)).map(x=>x.value);store.set("preferences",state.preferences);renderShell();};$("[data-clock12]",win).onchange=e=>{state.preferences.clock12=e.target.checked;savePrefs();};$("[data-calendar-mode]",win).onchange=e=>{state.preferences.calendar=e.target.value;savePrefs();};$("[data-notifications]",win).onclick=async()=>{if(!("Notification" in window)){notify("إشعارات النظام غير مدعومة هنا");return;}const result=await Notification.requestPermission();notify(result==="granted"?"تم تفعيل التذكيرات":"لم يتم السماح بالإشعارات");};}
function readImage(file,callback){if(!file)return;if(file.size>3*1024*1024){notify("اختر صورة أصغر من 3 MB");return;}const reader=new FileReader();reader.onload=()=>callback(reader.result);reader.readAsDataURL(file);}
function snapshotData(){return{version:3,time:Date.now(),notes:state.notes,noteFolders:state.noteFolders,tasks:state.tasks,files:state.files,profile:state.profile,preferences:state.preferences};}
function createAutoBackup(force=false){const last=state.backups[0]?.time||0;if(!force&&Date.now()-last<86400000)return;state.backups.unshift(snapshotData());state.backups=state.backups.slice(0,5);store.set("backups",state.backups);}
function restoreSnapshot(data){if(!data||!Array.isArray(data.notes)||!Array.isArray(data.tasks)||!Array.isArray(data.files))throw new Error("ملف النسخة غير صالح");state.notes=data.notes;state.noteFolders=data.noteFolders||[];state.tasks=data.tasks;state.files=data.files;state.profile=data.profile||state.profile;state.preferences=data.preferences||state.preferences;["notes","noteFolders","tasks","files","profile","preferences"].forEach(key=>store.set(key,state[key]));location.reload();}
function bindBackupSettings(win){const section=$("#data",win);section.insertAdjacentHTML("beforeend",`<hr><input data-backup-import type="file" accept="application/json"><button data-backup-now>نسخة محلية الآن</button><select data-backup-list><option value="">النسخ التلقائية</option>${state.backups.map((b,i)=>`<option value="${i}">${new Date(b.time).toLocaleString("ar-SA")}</option>`).join("")}</select><button data-backup-restore>استعادة المحددة</button><small>آخر نسخة: ${state.backups[0]?new Date(state.backups[0].time).toLocaleString("ar-SA"):"لا توجد"}</small>`);$("[data-backup-import]",section).onchange=async e=>{try{restoreSnapshot(JSON.parse(await e.target.files[0].text()));}catch(error){notify(error.message);}};$("[data-backup-now]",section).onclick=()=>{createAutoBackup(true);notify("تم إنشاء نسخة محلية");};$("[data-backup-restore]",section).onclick=()=>{const index=$("[data-backup-list]",section).value;if(index!=="")restoreSnapshot(state.backups[Number(index)]);};}
function setTheme(theme){document.body.dataset.theme=theme==="default"?"":theme;store.set("theme",theme);}
function applyPreferences(){setTheme(store.get("theme","default"));document.body.dataset.wallpaper=store.get("wallpaper","0");const p=state.preferences;document.documentElement.style.setProperty("--accent",p.accent||"");document.documentElement.style.setProperty("--wallpaper-blur",`${p.blur||0}px`);document.documentElement.style.setProperty("--wallpaper-brightness",String((p.wallpaperBrightness||100)/100));document.documentElement.style.setProperty("--dock-scale",String(p.dockScale||1));if(p.wallpaperData){$(".wallpaper").style.backgroundImage=`linear-gradient(rgba(7,17,31,.18),rgba(7,17,31,.35)),url(${p.wallpaperData})`;$(".wallpaper").style.backgroundSize="cover";$(".wallpaper").style.backgroundPosition="center";}if(store.get("largeText",false))document.documentElement.style.fontSize="18px";if(state.profile.avatar){$(".brand-mini").style.backgroundImage=`url(${state.profile.avatar})`;$(".brand-mini").style.backgroundSize="cover";$(".brand-mini").textContent="";}}

function updateSearch(query){const q=query.trim().toLowerCase(),apps=APPS.filter(a=>!q||a.name.includes(q)||a.id.includes(q)),notes=q?state.notes.filter(n=>(n.title+" "+n.body).toLowerCase().includes(q)):[],tasks=q?state.tasks.filter(t=>t.text.toLowerCase().includes(q)):[],files=q?state.files.filter(f=>f.name.toLowerCase().includes(q)):[];const rows=[...apps.map(a=>`<button class="search-result" data-open="${a.id}">${icon(a)}<span><strong>${a.name}</strong><br><small>تطبيق</small></span></button>`),...notes.map(n=>`<button class="search-result" data-open="notes"><span class="app-icon" style="--icon:#ffb82e">✎</span><span><strong>${escapeHTML(n.title)}</strong><br><small>ملاحظة</small></span></button>`),...tasks.map(t=>`<button class="search-result" data-open="tasks"><span class="app-icon" style="--icon:#38c98f">✓</span><span><strong>${escapeHTML(t.text)}</strong><br><small>مهمة</small></span></button>`),...files.map(f=>`<button class="search-result" data-open="files"><span class="app-icon" style="--icon:#2c8cff">◆</span><span><strong>${escapeHTML(f.name)}</strong><br><small>ملف</small></span></button>`)];$("#search-results").innerHTML=rows.join("")||"<p>لا توجد نتائج</p>";}
function bindGlobal(){
  document.addEventListener("click",async e=>{const open=e.target.closest("[data-open]");if(open)openApp(open.dataset.open);const switcher=e.target.closest("[data-switch-window]");if(switcher){const id=switcher.dataset.switchWindow;openApp(id);$("#task-switcher").hidden=true;}const action=e.target.closest("[data-action]")?.dataset.action;if(action==="launcher")togglePanel("launcher");if(action==="quick")togglePanel("quick");if(action==="search")togglePanel("search-panel");if(action==="taskswitcher"){renderTaskSwitcher();togglePanel("task-switcher");}if(action==="calendar"){renderCalendar();togglePanel("calendar");}if(action==="lock"){$("#lock-screen").hidden=false;closePanels();}if(action==="unlock")$("#lock-screen").hidden=true;if(action==="power")location.reload();if(action==="share"){if(navigator.share)await navigator.share({title:"NourBest OS",text:"مساحة العمل الهجينة الخاصة بي",url:location.href});else{await navigator.clipboard?.writeText(location.href);notify("تم نسخ رابط النظام");}}if(action==="finish-onboarding"){state.profile.name=$("#profile-name").value.trim();store.set("profile",state.profile);store.set("onboarded",true);$("#onboarding").hidden=true;tick();notify("تم إعداد مساحتك");}if(action==="apply-update"){navigator.serviceWorker.getRegistration().then(r=>{r?.waiting?.postMessage({type:"SKIP_WAITING"});location.reload();});}const close=e.target.closest("[data-close]");if(close)$("#"+close.dataset.close).hidden=true;});
  document.addEventListener("click",e=>{const action=e.target.closest("[data-action]")?.dataset.action;if(action==="desktops"){renderDesktopSwitcher();togglePanel("desktop-switcher");}const desktop=e.target.closest("[data-desktop]");if(desktop)switchDesktop(Number(desktop.dataset.desktop));const layout=e.target.closest("[data-layout]");if(layout){arrangeWindows(layout.dataset.layout);closePanels();}const move=e.target.closest("[data-move-window]");if(move){const win=state.windows.get(move.dataset.moveWindow);if(win){win.dataset.desktop=String((Number(win.dataset.desktop)+1)%3);store.set(`windowDesktop:${move.dataset.moveWindow}`,Number(win.dataset.desktop));applyDesktopVisibility();renderTaskSwitcher();}}const context=e.target.closest("[data-context-action]");if(context&&state.contextWindow){const id=state.contextWindow,win=state.windows.get(id),type=context.dataset.contextAction;if(type==="close")closeApp(id);else if(type==="move-desktop"){win.dataset.desktop=String((Number(win.dataset.desktop)+1)%3);store.set(`windowDesktop:${id}`,Number(win.dataset.desktop));applyDesktopVisibility();}else if(win){const top=type.includes("bottom")?"50%":"0",left=type.includes("left")?"0":"50%";Object.assign(win.style,{top,left,width:"50%",height:"calc(50% - 41px)",transform:"none"});storeWindowLayout(id,win);}$("#window-context").hidden=true;}});
  document.addEventListener("pointerdown",e=>{if(e.target.closest(".panel,[data-action]"))return;closePanels();});
  $("#launcher-search").addEventListener("input",e=>{const q=e.target.value.toLowerCase();$$('.app-card').forEach(c=>c.hidden=!c.textContent.toLowerCase().includes(q));});
  $("#global-search").addEventListener("input",e=>updateSearch(e.target.value));
  $$("[data-toggle]").forEach(b=>b.onclick=()=>{const type=b.dataset.toggle;if(type==="wifi"){$("small",b).textContent=navigator.onLine?"متصل":"غير متصل";notify("إدارة شبكة الجهاز نفسها متاحة من إعدادات النظام المضيف");return;}b.classList.toggle("active");const active=b.classList.contains("active");$("small",b).textContent=active?"مفعّل":"متوقف";if(type==="focus")system.classList.toggle("focus-mode",active);if(type==="night")setTheme(active?"violet":"default");if(type==="sound")store.set("interfaceSound",active);});
  $("#brightness").oninput=e=>document.documentElement.style.setProperty("--brightness",e.target.value/100);
  window.addEventListener("keydown",e=>{if(isEditable(e.target))return;if(e.key==="Escape"){closePanels();return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="k"){e.preventDefault();togglePanel("search-panel");}if(e.ctrlKey&&e.altKey&&/[123]/.test(e.key)){e.preventDefault();switchDesktop(Number(e.key)-1);}if(e.ctrlKey&&e.shiftKey&&["ArrowLeft","ArrowRight","ArrowUp"].includes(e.key)&&state.active){const win=state.windows.get(state.active);if(e.key==="ArrowUp")win.classList.toggle("maximized");else Object.assign(win.style,{left:e.key==="ArrowLeft"?"0":"50%",top:"0",width:"50%",height:"calc(100% - 82px)",transform:"none"});storeWindowLayout(state.active,win);}});
  window.addEventListener("online",()=>{$("#network-state").textContent="متصل بالإنترنت";notify("عاد الاتصال بالإنترنت");}); window.addEventListener("offline",()=>{$("#network-state").textContent="وضع دون إنترنت";notify("النظام يعمل دون إنترنت");});
  window.addEventListener("beforeinstallprompt",e=>{e.preventDefault();installPrompt=e;});
  window.addEventListener("error",e=>systemLog("error",e.message||"خطأ غير معروف"));window.addEventListener("unhandledrejection",e=>systemLog("promise",e.reason?.message||e.reason));
  let swipeStart=null;$("#desktop").addEventListener("pointerdown",e=>{if(innerWidth<721)swipeStart={x:e.clientX,y:e.clientY};});$("#desktop").addEventListener("pointerup",e=>{if(!swipeStart)return;const dy=e.clientY-swipeStart.y;if(dy<-90){renderTaskSwitcher();togglePanel("task-switcher");}if(dy>90)togglePanel("launcher");swipeStart=null;});
  window.addEventListener("resize",()=>{$$(".app-window").forEach(win=>{const r=win.getBoundingClientRect();if(r.left>innerWidth-100||r.top>innerHeight-100){win.style.left="50%";win.style.top="5%";win.style.transform="translateX(-50%)";}});});
}

async function boot(){
  if(window.NourDB){try{const saved=await NourDB.hydrate(["notes","noteFolders","tasks","files","profile","preferences","backups","logs"]);if(saved.notes)state.notes=saved.notes;if(saved.noteFolders)state.noteFolders=saved.noteFolders;if(saved.tasks)state.tasks=saved.tasks;if(saved.files)state.files=saved.files;if(saved.profile)state.profile=saved.profile;if(saved.preferences)state.preferences=saved.preferences;if(saved.backups)state.backups=saved.backups;if(saved.logs)state.logs=saved.logs;}catch(error){systemLog("database",error.message);}}
  store.set("schemaVersion",3);createAutoBackup();renderShell();bindGlobal();tick();setInterval(tick,1000);renderCalendar();checkTaskReminders();setInterval(checkTaskReminders,30000);
  if("serviceWorker" in navigator){try{const registration=await navigator.serviceWorker.register("./sw.js");if(registration.waiting)$("#update-banner").hidden=false;registration.addEventListener("updatefound",()=>{const worker=registration.installing;worker?.addEventListener("statechange",()=>{if(worker.state==="installed"&&navigator.serviceWorker.controller)$("#update-banner").hidden=false;});});navigator.serviceWorker.addEventListener("controllerchange",()=>location.reload());}catch(err){console.warn("Service worker unavailable",err);}}
  if(navigator.getBattery){try{const battery=await navigator.getBattery();const updateBattery=()=>{$("#device-label").textContent+=` · ${Math.round(battery.level*100)}%${battery.charging?" ⚡":""}`;};updateBattery();battery.addEventListener("levelchange",updateBattery);}catch{}}
  const status=$("#boot-status");for(const [text,delay] of [["تحميل Nour Shell…",250],["تشغيل الخدمات المحلية…",260],["النظام جاهز",220]]){status.textContent=text;await new Promise(r=>setTimeout(r,delay));}
  $("#boot").remove();system.hidden=false;
  if(!store.get("onboarded",false))$("#onboarding").hidden=false;
  const requested=new URLSearchParams(location.search).get("app");if(requested)openApp(requested);else store.get("openApps",[]).filter(id=>appById(id)).forEach(id=>openApp(id));applyDesktopVisibility();
}

boot();
